/** Removes this node from the list. Returns `true` when removed successfully, or `false` if the node was already removed or if it was not added to any list in the first place. */
public open fun remove(): Boolean {
    while (true) { // lock-free loop on next
        val next = this.next
        // was already removed -- don't try to help (original thread will take care)
        if (next is Removed) {
            return false
        }
        if (next === this) return false // was not even added
        val removed = (next as Node).removed()
        if (_next.compareAndSet(next, removed)) {
            // was removed successfully (linearized remove) -- fixup the list
            finishRemove(next)
            return true
        }
    }
}
