internal suspend fun loadToken(): T? {
    if (!cacheTokens) {
        return loadTokens()
    }

    if (value != null) return value // Hot path
    val prevValue = value

    return if (currentCoroutineContext()[SetTokenContext] != null) { // Already locked by setToken
        value = loadTokens()
        value
    } else {
        mutex.withLock {
            isLoadRequest = true
            try {
                if (prevValue == value) { // Raced first
                    value = loadTokens()
                }
            } finally {
                isLoadRequest = false
            }

            value
        }
    }
}
