internal suspend fun delayGMTDate(milliseconds: Long) {
    var delayValue = milliseconds

    do {
        val start = GMTDate()
        delay(delayValue.milliseconds)
        val end = GMTDate()
        if (end > start + milliseconds) {
            break
        }
        if (delayValue != 1L) {
            delayValue = 1L
        }
    } while (true)
}
```

