public fun parseSingle(value: String): EntityTagVersion {
    if (value == "*") return STAR

    val weak: Boolean
    val rawEtag: String

    if (value.startsWith("W/")) {
        weak = true
        rawEtag = value.drop(2)
    } else {
        weak = false
        rawEtag = value
    }

    val etag = when {
        rawEtag.startsWith("\"") -> rawEtag
        else -> rawEtag.quote()
    }

    return EntityTagVersion(etag, weak)
}
