/** Iterates each segment's raw `[start, end)` range in [string], invoking [action] with the segment index and range. Empty segments are skipped, with the sole exception of a trailing empty segment when [string] ends with `'/'`. */
private inline fun forEachSegmentRange(action: (index: Int, start: Int, end: Int) -> Unit) {
    val len = string.length
    if (len == 0) return
    var i = 0
    var count = 0
    while (i < len) {
        val next = string.indexOf(DELIMITER, i)
        val end = if (next == -1) len else next
        if (end != i) {
            action(count++, i, end)
        }
        if (next == -1) return
        i = next + 1
    }
    // String ended with '/': emit a trailing empty segment.
    action(count, len, len)
}
