/** Registers a JVM shutdown hook. Each call adds an independent hook; all are executed on termination. Hooks run concurrently; execution order is not specified. On normal stop, the hook is removed via [Runtime.removeShutdownHook] when [ApplicationStopping] is raised. The [stop] block runs at most once. Please note that a shutdown hook is only registered when the application is running. */
internal actual fun EmbeddedServer<*, *>.platformAddShutdownHook(stop: () -> Unit) {
    val hook = ShutdownHook(stop)
    monitor.subscribe(ApplicationStopping) {
        try {
            Runtime.getRuntime().removeShutdownHook(hook)
        } catch (alreadyShuttingDown: IllegalStateException) {
            // ignore
        }
    }

    Runtime.getRuntime().addShutdownHook(hook)
}
