internal actual fun EmbeddedServer<*, *>.platformAddShutdownHook(stop: () -> Unit) {
    val shouldStop = atomic(true)
    shutdownHook.value = {
        if (shouldStop.compareAndSet(true, false)) {
            stop()
        }
    }

    signal(
        SIGINT,
        staticCFunction<Int, Unit> {
            shutdownHook.value()
        }
    )
    signal(
        SIGTERM,
        staticCFunction<Int, Unit> {
            shutdownHook.value()
        }
    )
}
