```kotlin
/** Registers a POSIX signal handler for shutdown. Each call replaces the previous callback; only the last registered [stop] block is kept; the built-in [EmbeddedServer.start] hook typically wins. The listener is not removed on normal stop, but the [stop] block still runs at most once. Please note that a shutdown hook is only registered when the application is running. */
internal actual fun EmbeddedServer<*, *>.platformAddShutdownHook(stop: () -> Unit) {
    val shouldStop = atomic(true)
    shutdownHook.value = {
        if (shouldStop.compareAndSet(true, false)) {
            stop()
        }
    }

    signal(
        SIGINT,
        staticCFunction<Int, Unit> {
            shutdownHook.value()
        }
    )
    signal(
        SIGTERM,
        staticCFunction<Int, Unit> {
            shutdownHook.value()
        }
    )
}
