internal suspend fun transferByteBuf(content: ByteBuf, bc: ByteWriteChannel) {
    while (content.readableBytes() > 0) {
        bc.write { bb ->
            val size = content.readableBytes()
            if (bb.remaining() > size) {
                val l = bb.limit()
                bb.limit(bb.position() + size)
                content.readBytes(bb)
                bb.limit(l)
            } else {
                content.readBytes(bb)
            }
        }
    }
    bc.flush()
}
