public fun Route.install(flow: OAuth2Flow) {
    val scheme = flow.oauthScheme
    val route = installOAuthRoute(scheme)
    val plugin = scheme.createPlugin(
        isOptional = false,
        onUnauthorized = null // keep default OAuth redirect
    )
    route.install(plugin)

