public suspend fun AuthenticationContext.processFailure(
    failure: AuthenticationFailedCause,
    handler: UnauthorizedHandler?
) {
    if (call.isHandled) {
        return
    }
    if (handler != null) {
        with(handler) {
            call.toRoutingContext().onUnauthorized(cause = failure)
        }
        if (call.isHandled) return
    }
    rejectUnhandledCall()
}
