public suspend fun HttpClient.fetchOpenIdMetadata(issuer: String): OpenIdProviderMetadata {
    val config = try {
        get {
            expectSuccess = true
            url.takeFrom(issuer)
            url.appendPathSegments(".well-known", "openid-configuration")
        }.body<OpenIdProviderMetadata>()
    } catch (e: CancellationException) {
        throw e
    } catch (e: Exception) {
        throw OidcDiscoveryException("Failed to fetch OpenID configuration from '$issuer'", e)
    }
    config.validate(expectedIssuer = issuer)
    return config
}
