private suspend fun <Stream : Flushable, T> serialize(
    flow: Flow<T>,
    jGenerator: JsonGenerator,
    stream: Stream
) {
    jGenerator.setup()
    jGenerator.writeStartArray()

    flow.collect { value ->
        jGenerator.writeObject(value)
        stream.flush()
    }

    jGenerator.writeEndArray()
    jGenerator.flush()
    stream.flush()
}
