/** UTF-8 byte length of the character at [index], treating a valid surrogate pair (whose low half is at `index + 1`) as a single 4-byte code point. Matches [String.encodeToByteArray]: a lone surrogate counts as the 3-byte replacement character. A returned value of `4` therefore means the character spans two code units (advance the index by 2); any other value means one (advance by 1). */
private fun String.utf8ByteCountAt(index: Int): Int {
    val code = this[index].code
    return when {
        code < 0x80 -> 1
        code < 0x800 -> 2
        this[index].isHighSurrogate() && index + 1 < length && this[index + 1].isLowSurrogate() -> 4
        else -> 3
    }
}
