```kotlin
/** Returns unchanged string if it shorter than [maxSize] UTF-8 bytes, otherwise drops trailing characters until the UTF-8 encoding fits. Truncation happens on whole characters, so multibyte characters are never split, and the result stays decodable. */
internal fun String.utf8Truncate(maxSize: Int): String {
    var size = 0
    var index = 0
    while (index < length) {
        val bytes = utf8ByteCountAt(index)
        if (size + bytes > maxSize) break
        size += bytes
        index += if (bytes == 4) 2 else 1
    }
    return if (index == length) this else substring(0, index)
}
